from pathlib import Path
import hashlib,json,datetime
R=Path(__file__).resolve().parent
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
inputs=json.loads((R/'inputs.json').read_bytes())
for name,pin in inputs['pins'].items():assert sha(R/'source'/name)==pin
node=json.loads((R/'independent-node-02.stdout.raw').read_bytes());paths=json.loads((R/'independent-path.stdout.raw').read_bytes())
assert node['passed']==7 and paths['passed']==8
for phase in ['independent-node-02','independent-path']:assert json.loads((R/(phase+'.result.json')).read_bytes())['exit_code']==0
source=(R/'source/real-electron-flow.mjs').read_text(encoding='utf-8')
ui=R.parents[1]/'product-v1-assistant-startup-author/final/source/apps/web/src/workbench.jsx'
text=ui.read_text(encoding='utf-8');entry=text[text.index('export function NativeProjectEntry('):text.index('export function DesktopQualification(')]
assert all(s in source for s in ["getByLabel('项目显示名称'","name: '选择本地项目目录'","name: '配置模型并打开工作台'"])
assert all(s not in entry for s in ['项目显示名称','选择本地项目目录','配置模型并打开工作台'])
assert all(s in entry for s in ['<summary>自定义项目名称</summary>','<label>显示名称','选择目录','打开工作台'])
